"""Five complete cello movements; original sounding pitch, all source voices/repeats."""
import argparse,hashlib,json,subprocess,tempfile
from pathlib import Path
from import_bwv1012 import read_notes
from import_repertoire_batch4 import VOICE_MIDI
from import_bwv1006a_complete import expand
ROOT=Path(__file__).resolve().parents[1];SOURCES=ROOT/'scripts/score-sources/bwv1009-complete'
PIECES=[
 dict(key='prelude1009',name='prelude',number=1,title='Prélude',jp='プレリュード',meter=[3,4],bpm=120,tempoBasis='source wrapper quarter=120',writtenBars=88,beats=264,form=[[0,264]],last=262),
 dict(key='allemande1009',name='allemande',number=2,title='Allemande',jp='アルマンド',meter=[4,4],bpm=84,tempoBasis='fixed audition choice; wrapper has no explicit tempo',writtenBars=24,beats=192,form=[[0,48],[0,48],[48,96],[48,96]],last=191.75),
 dict(key='courante1009',name='courante',number=3,title='Courante',jp='クーラント',meter=[3,4],bpm=210,tempoBasis='source wrapper dotted-half=70, equivalent quarter=210',writtenBars=84,beats=504,form=[[0,120],[0,120],[120,252],[120,252]],last=503.5),
 dict(key='sarabande1009',name='sarabande',number=4,title='Sarabande',jp='サラバンド',meter=[3,4],bpm=60,tempoBasis='fixed audition choice; wrapper has no explicit tempo',writtenBars=24,beats=144,form=[[0,24],[0,24],[24,72],[24,72]],last=144),
 dict(key='gigue1009',name='gigue',number=6,title='Gigue',jp='ジーグ',meter=[3,8],bpm=97.5,tempoBasis='source wrapper dotted-quarter=65, equivalent quarter=97.5',writtenBars=108,beats=324,form=[[0,72],[0,72],[72,162],[72,162]],last=324)
]
def source_file(p):return f"cellosuite3_{p['number']}_{p['name']}.ly"
def compile_midi(executable):
 with tempfile.TemporaryDirectory() as directory:
  for p in PIECES:
   text=subprocess.run([str(Path(executable).with_name('convert-ly')),str(SOURCES/source_file(p))],capture_output=True,text=True,check=True).stdout
   for mode in ['raw','full']+([] if p['name']=='prelude' else ['first']):
    music=text
    if mode=='first':
     pos=music.index('\\repeat volta');start=music.index('{',pos);depth=1;i=start+1
     while depth:
      if music[i]=='{':depth+=1
      elif music[i]=='}':depth-=1
      i+=1
     music=music[:pos]+music[start+1:i-1]+'}\n'
    music+='\n\\score { { \\clef "bass" '+('\\unfoldRepeats ' if mode=='full' else '')+'\\'+p['name']+' } \\midi { '+VOICE_MIDI+' } }\n'
    f=Path(directory)/(p['name']+'-'+mode+'.ly');f.write_text(music)
    subprocess.run([executable,'-dno-print-pages','-dbackend=null','-o',str(SOURCES/(p['name']+'-'+mode)),str(f)],check=True)
def build():
 songs,manifest={},[]
 for p in PIECES:
  raw=read_notes((SOURCES/(p['name']+'-raw.midi')).read_bytes());full=read_notes((SOURCES/(p['name']+'-full.midi')).read_bytes());manual,end=expand(raw,p['form'])
  assert manual==full and end==p['beats'];assert max(a+d for a,pitch,d in full)==p['last']
  source=dict(credit='J. S. Bach / Stelios Samelis / Mutopia (2018), Bach Gesellschaft edition',license='Public Domain',licenseUrl='https://creativecommons.org/licenses/publicdomain/',url='https://www.mutopiaproject.org/cgibin/piece-info.cgi?id=890',modifications='Complete individual movement. '+('No repeat signs.' if p['name']=='prelude' else 'Both volta sections repeated: A A B B.')+' convert-ly/LilyPond2.24.4; separate MIDI voices, all notes/holds/unisons retained. Source cello sounding pitch, shift0. Source rests included. Trill signs and expressive bowing/dynamics not realized. Tempo: '+p['tempoBasis']+'. App articulation separate.',pitch='Original C-major cello sounding pitches, shift0; no guitar octave-notation conversion. C2 and other notes below standard guitar E2 retained. NOT a guitar arrangement or verified six-string fingering; no tuning settings applied.',terms='Score edition placed in the public domain by typesetter Stelios Samelis. Source and modification records retained; application code separate.',endingStatus=f"終端{p['beats']}拍／最後の発音終端{p['last']}拍。版の休符を保持。")
  assert all(len(v)<=500 for v in source.values())
  title='J. S. Bach · BWV 1009 — '+p['title']
  songs[p['key']]=dict(score=dict(title=title,bpm=p['bpm'],meter=p['meter'],endBeat=end,events=full),label=title,option=p['title']+'（'+p['jp']+'）',edition='全楽章・'+('反復なし' if p['name']=='prelude' else '反復あり')+'・チェロ原音域（E2未満あり）',source=source)
  files=[source_file(p),'header.ily','cellosuite3.ly','cellosuite3_5_bourree.ly']+[p['name']+'-'+m+'.midi' for m in ['raw','full']+([] if p['name']=='prelude' else ['first'])]
  manifest.append({**p,'source':source,'rawNotes':len(raw),'notes':len(full),'pitchRange':[min(e[1] for e in full),max(e[1] for e in full)],'belowE2':sum(e[1]<40 for e in full),'lilypondUrl':'https://raw.githubusercontent.com/MutopiaProject/MutopiaProject/master/ftp/BachJS/BWV1009/cellosuite3/cellosuite3-lys/'+source_file(p),'sha256':{f:hashlib.sha256((SOURCES/f).read_bytes()).hexdigest() for f in files}})
 (ROOT/'synth-demo/bwv1009-complete.js').write_text('// Generated by scripts/import_bwv1009_complete.py. Score edition Public Domain, Stelios Samelis/Mutopia; source metadata retained.\nconst bwv1009Complete = '+json.dumps(songs,ensure_ascii=False,separators=(',',':')).replace('],[','],\n[')+';\n')
 (SOURCES/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n');print([(p['key'],p['notes'],p['beats'],p['pitchRange'],p['belowE2']) for p in manifest])
if __name__=='__main__':
 parser=argparse.ArgumentParser();parser.add_argument('--lilypond');args=parser.parse_args()
 if args.lilypond:compile_midi(args.lilypond)
 build()
